import{_ as l,l as o,o as e,c as i,v as r,p as n,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"领域专用加速器","description":"","frontmatter":{"title":"领域专用加速器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dsa-accelerator.md","filePath":"cs/dsa-accelerator.md","lastUpdated":1789023840000}'),h={name:"cs/dsa-accelerator.md"};function A(m,a,_,f,u,C){const s=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="领域专用加速器" tabindex="-1">领域专用加速器 <a class="header-anchor" href="#领域专用加速器" aria-label="Permalink to &quot;领域专用加速器&quot;">​</a></h1><div class="epigraph"><p>把热点循环的数据路径硬化，去掉通用译码、重命名与一致性的税；换来的是硅与编译器都只服务一类算法。</p><footer>—— 据 Dally, Turakhia, and Han, Domain-Specific Hardware Accelerators, CACM 2020；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/systolic-array">上一课</a> 给出一种硬化形状。<a href="/cs/vliw-epic">VLIW</a> 仍是可编程指令束。本课不重画 PE 网格。缺口是 <strong>DSA：为领域固定流水、存储层次与数值格式，CPU 只做编排。</strong> 本栏不重写 Transformer 训练栈——那是大模型栏；这里只谈「为何通用乱序核不够、加速器收走哪一笔税」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/deep-pipeline-clock">深流水</a> 与 <a href="/cs/issue-queue-wakeup">IQ 唤醒</a> 服务任意程序。热点若稳定（编解码、密码、稠密线性代数），每拍都在付通用税。缺口不是再加 SIMT 占用率，而是<strong>用固定或轻度可编程的数据路径跑那一类循环，用 DMA 与队列和 CPU 衔接。</strong></p><p><span class="marginnote">Dally 等强调：专用化吃的是可编程性与 Amdahl 的串行/不规则段。接口、缓存一致性是否参与、虚拟内存，是 SoC 课的问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加速器：专用 PE + 本地 SRAM + DMA。CPU：系统调用或用户态队列提交作业，fence 等完成。一致性：有的参与 <a href="/cs/directory-scalability">目录</a>（贵），有的用显式拷贝。数值：窄类型、饱和算术，ISA 通用核不必有。</p>',8)),(e(),n(p,null,{default:t(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CPU%5B%22CPU%20%E7%BC%96%E6%8E%92%22%5D%20--%3E%20Q%5B%22%E4%BD%9C%E4%B8%9A%E9%98%9F%E5%88%97%20%2F%20DMA%22%5D%0A%20%20Q%20--%3E%20DSA%5B%22%E7%A1%AC%E5%8C%96%E6%95%B0%E6%8D%AE%E8%B7%AF%E5%BE%84%22%5D%0A%20%20DSA%20--%3E%20MEM%5B%22%E6%9C%AC%E5%9C%B0%20SRAM%20%E6%88%96%20HBM%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/cpi-amdahl">阿姆达尔</a>：加速比受不能卸载的段限制。与 GPU：GPU 仍是宽可编程 SIMT；DSA 更窄。与量化栏的金融加速无关：本课不写 LOB。与大模型栏：张量核属于 DSA 家族，细节不在本课展开。</p><p>虚拟内存与 IOMMU：加速器若直接用用户指针，要走地址翻译与权限，否则只能 DMA 物理缓冲。一致性参与则目录流量涨，不参与则必须显式 flush/invalidate。这是 SoC 集成税，不是算法税。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列产品清单。近存计算下一课把「DMA 进来算」改成「在内存侧算」。异构 SoC 再下一课把大小核与加速器放在同一硅上。</p><p>后课默认：领域热点可以卸载。数据搬运本身若占主导，应考虑近存。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DSA 去掉通用前端与一致性税，服务稳定热点。</li><li>加速比受编排与不可卸载段限制。</li><li>把运算挪到内存侧是下一课 PIM。</li><li>出处：Dally, Turakhia, Han, <em>CACM</em>, 2020；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const S=l(h,[["render",A]]);export{D as __pageData,S as default};
